//! Windows-compatible IPv4 and Ethernet address parsing/formatting helpers.
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;
fn parse_v4(s:&[u8],strict:bool)->Option<([u8;4],usize)>{let mut out=[0u8;4];let mut i=0;for part in 0..4{let start=i;let mut v=0u32;while i<s.len()&&s[i].is_ascii_digit(){if strict&&i==start&&s[i]==b'0'&&i+1<s.len()&&s[i+1].is_ascii_digit(){return None;}v=v*10+(s[i]-b'0') as u32;if v>255{return None;}i+=1;}if i==start{return None;}out[part]=v as u8;if part<3{if i>=s.len()||s[i]!=b'.'{return None;}i+=1;}}Some((out,i))}
fn format_v4(a:[u8;4],out:&mut [u8;16])->usize{let mut p=0;for j in 0..4{let mut v=a[j];let mut tmp=[0u8;3];let mut n=0;loop{tmp[n]=b'0'+v%10;n+=1;v/=10;if v==0{break;}}for k in (0..n).rev(){out[p]=tmp[k];p+=1;}if j<3{out[p]=b'.';p+=1;}}p}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv4_string_to_address_a(s:*const u8,strict:u8,term:*mut *const u8,address:*mut u32)->i32{if s.is_null()||term.is_null()||address.is_null(){return INVALID;}let mut n=0usize;while n<64&&unsafe{*s.add(n)}!=0{n+=1;}let bytes=unsafe{core::slice::from_raw_parts(s,n)};let Some((a,used))=parse_v4(bytes,strict!=0)else{return INVALID;};unsafe{*term=s.add(used);core::ptr::copy_nonoverlapping(a.as_ptr(),address as *mut u8,4);}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv4_string_to_address_w(s:*const u16,strict:u8,term:*mut *const u16,address:*mut u32)->i32{if s.is_null()||term.is_null()||address.is_null(){return INVALID;}let mut n=0usize;while n<64&&unsafe{*s.add(n)}!=0{n+=1;}let mut b=[0u8;64];for i in 0..n{let c=unsafe{*s.add(i)};if c>127{return INVALID;}b[i]=c as u8;}let Some((a,used))=parse_v4(&b[..n],strict!=0)else{return INVALID;};unsafe{*term=s.add(used);core::ptr::copy_nonoverlapping(a.as_ptr(),address as *mut u8,4);}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv4_string_to_address_ex_a(s:*const u8,strict:u8,address:*mut u32,port:*mut u16)->i32{if s.is_null()||address.is_null()||port.is_null(){return INVALID;}let mut n=0usize;while n<80&&unsafe{*s.add(n)}!=0{n+=1;}let bytes=unsafe{core::slice::from_raw_parts(s,n)};let Some((a,used))=parse_v4(bytes,strict!=0)else{return INVALID;};let mut p=0u16;if used<n{if bytes[used]!=b':'||used+1>=n{return INVALID;}let mut x=0u32;for c in &bytes[used+1..]{if !c.is_ascii_digit(){return INVALID;}x=x*10+(*c-b'0') as u32;if x>65535{return INVALID;}}p=x as u16;}unsafe{core::ptr::copy_nonoverlapping(a.as_ptr(),address as *mut u8,4);*port=p;}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv4_string_to_address_ex_w(s:*const u16,strict:u8,address:*mut u32,port:*mut u16)->i32{if s.is_null(){return INVALID;}let mut b=[0u8;80];let mut n=0;while n<80{let c=unsafe{*s.add(n)};if c==0{break;}if c>127{return INVALID;}b[n]=c as u8;n+=1;}if n==80{return INVALID;}unsafe{b[n]=0;rtl_ipv4_string_to_address_ex_a(b.as_ptr(),strict,address,port)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv4_address_to_string_ex_a(address:*const u32,port:u16,dst:*mut u8,length:*mut u32)->i32{if address.is_null()||dst.is_null()||length.is_null(){return INVALID;}let mut b=[0u8;16];let a=unsafe{core::slice::from_raw_parts(address as *const u8,4)};let mut n=format_v4([a[0],a[1],a[2],a[3]],&mut b);if port!=0{b[n]=b':';n+=1;let mut t=[0u8;5];let mut k=0;let mut p=port;loop{t[k]=b'0'+(p%10) as u8;k+=1;p/=10;if p==0{break;}}for j in (0..k).rev(){b[n]=t[j];n+=1;}}let cap=unsafe{*length} as usize;if cap<n+1{unsafe{*length=(n+1) as u32;}return SMALL;}unsafe{core::ptr::copy_nonoverlapping(b.as_ptr(),dst,n);*dst.add(n)=0;*length=(n+1) as u32;}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv4_address_to_string_ex_w(address:*const u32,port:u16,dst:*mut u16,length:*mut u32)->i32{if address.is_null()||dst.is_null()||length.is_null(){return INVALID;}let mut b=[0u8;16];let a=unsafe{core::slice::from_raw_parts(address as *const u8,4)};let mut n=format_v4([a[0],a[1],a[2],a[3]],&mut b);if port!=0{b[n]=b':';n+=1;let mut t=[0u8;5];let mut k=0;let mut p=port;loop{t[k]=b'0'+(p%10) as u8;k+=1;p/=10;if p==0{break;}}for j in (0..k).rev(){b[n]=t[j];n+=1;}}let cap=unsafe{*length} as usize;if cap<n+1{unsafe{*length=(n+1) as u32;}return SMALL;}for i in 0..n{unsafe{*dst.add(i)=b[i] as u16;}}unsafe{*dst.add(n)=0;*length=(n+1) as u32;}SUCCESS}
fn parse_mac(s:&[u8])->Option<([u8;6],usize)>{let mut a=[0u8;6];let mut i=0;for j in 0..6{if i+2>s.len(){return None;}let hi=hex(s[i])?;let lo=hex(s[i+1])?;a[j]=(hi<<4)|lo;i+=2;if j<5{if i>=s.len()||!matches!(s[i],b'-'|b':'){return None;}i+=1;}}Some((a,i))}
fn hex(c:u8)->Option<u8>{match c{b'0'..=b'9'=>Some(c-b'0'),b'a'..=b'f'=>Some(c-b'a'+10),b'A'..=b'F'=>Some(c-b'A'+10),_=>None}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ethernet_string_to_address_a(s:*const u8,term:*mut *const u8,address:*mut u8)->i32{if s.is_null()||term.is_null()||address.is_null(){return INVALID;}let mut n=0;while n<64&&unsafe{*s.add(n)}!=0{n+=1;}let Some((a,used))=parse_mac(unsafe{core::slice::from_raw_parts(s,n)})else{return INVALID;};unsafe{core::ptr::copy_nonoverlapping(a.as_ptr(),address,6);*term=s.add(used);}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ethernet_string_to_address_w(s:*const u16,term:*mut *const u16,address:*mut u8)->i32{if s.is_null()||term.is_null()||address.is_null(){return INVALID;}let mut b=[0u8;64];let mut n=0;while n<64{let c=unsafe{*s.add(n)};if c==0{break;}if c>127{return INVALID;}b[n]=c as u8;n+=1;}let Some((a,used))=parse_mac(&b[..n])else{return INVALID;};unsafe{core::ptr::copy_nonoverlapping(a.as_ptr(),address,6);*term=s.add(used);}SUCCESS}
